using System.Security.Claims;using DadoRetail.Api.Security;using DadoRetail.Application.Security;using DadoRetail.Domain.Payments;using DadoRetail.Domain.Sales;using DadoRetail.Infrastructure.Persistence;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace DadoRetail.Api.Controllers;[ApiController,Route("api/v1/sales")]public sealed class SalesController(DadoRetailDbContext db):ControllerBase{[HttpPost,HasPermission(Permissions.SaleCreate)]public async Task<IActionResult>Create(CreateSaleRequest r,CancellationToken ct){if(!Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier)??User.FindFirstValue("sub"),out var cashierId))return Unauthorized();var sale=new Sale(r.StoreId,r.CashRegisterId,cashierId);db.Sales.Add(sale);await db.SaveChangesAsync(ct);return Ok(new{sale.Id,sale.Status});}[HttpPost("{id:guid}/items/by-barcode"),HasPermission(Permissions.SaleCreate)]public async Task<IActionResult>AddByBarcode(Guid id,AddBarcodeItemRequest r,CancellationToken ct){var sale=await db.Sales.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==id,ct);if(sale is null)return NotFound();var productId=await db.Barcodes.Where(x=>x.Value==r.Barcode).Select(x=>(Guid?)x.ProductId).FirstOrDefaultAsync(ct);if(productId is null)return NotFound(new{message="Штрихкод не найден"});var now=DateTime.UtcNow;var price=await db.Prices.Where(x=>x.ProductId==productId&&x.StoreId==sale.StoreId&&x.IsActive&&x.ValidFromUtc<=now&&(x.ValidToUtc==null||x.ValidToUtc>now)).OrderByDescending(x=>x.ValidFromUtc).Select(x=>(decimal?)x.Amount).FirstOrDefaultAsync(ct);if(price is null)return Conflict(new{message="Для товара нет действующей цены"});sale.AddItem(productId.Value,r.Quantity<=0?1:r.Quantity,price.Value);await db.SaveChangesAsync(ct);return Ok(new{sale.Id,sale.Total,sale.Items});}[HttpPost("{id:guid}/payments"),HasPermission(Permissions.SaleCreate)]public async Task<IActionResult>CreatePayment(Guid id,CreatePaymentRequest r,CancellationToken ct){var sale=await db.Sales.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==id,ct);if(sale is null)return NotFound();if(sale.Total<=0)return BadRequest(new{message="Пустой чек"});var already=await db.Payments.Where(x=>x.SaleId==id&&x.Status==PaymentStatus.Paid).SumAsync(x=>(decimal?)x.Amount,ct)??0;var amount=r.Amount<=0?sale.Total-already:r.Amount;if(amount<=0||already+amount>sale.Total)return BadRequest(new{message="Некорректная сумма оплаты"});var p=new Payment(sale.Id,amount,r.Method);db.Payments.Add(p);await db.SaveChangesAsync(ct);return Ok(new{p.Id,p.Amount,p.Method,p.Status});}[HttpGet("{id:guid}"),HasPermission(Permissions.SaleCreate)]public async Task<IActionResult>Get(Guid id,CancellationToken ct){var s=await db.Sales.AsNoTracking().Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==id,ct);return s is null?NotFound():Ok(new{s.Id,s.StoreId,s.CashRegisterId,s.CashierId,s.Status,s.Total,s.Items});}}public sealed record CreateSaleRequest(Guid StoreId,Guid CashRegisterId);public sealed record AddBarcodeItemRequest(string Barcode,decimal Quantity);public sealed record CreatePaymentRequest(PaymentMethod Method,decimal Amount);
